import { createWaterWorld, waterPhysicalConfig, waterSolverConfig, WaterHydrodynamics } from '../dist/fluids/water/index.js';
import test from 'node:test';
import assert from 'node:assert/strict';
import { FluidWorld, FluidConfig, FluidError, Vec3, LiquidSolverConfig } from '../dist/index.js';
const V=(x,y,z)=>Vec3.of(x,y,z);
const P=(x,y,z,m=1,v=V(0,0,0))=>({position:V(x,y,z),velocity:v,massKg:m});
const physical=(g=V(0,0,0),n=64)=>FluidConfig.create({restDensityKgM3:1000,gravityMS2:g,maxSubstepSeconds:1/120,maxSubsteps:n});
const liquid=(options={})=>LiquidSolverConfig.create({...waterSolverConfig(),supportRadiusMeters:.6,...options});
const create=(g=V(0,0,0))=>{let w=new FluidWorld(physical(g));w.setLiquidConfig(liquid());return w};
const fails=code=>e=>e instanceof FluidError&&e.code===code;
const close=(a,b,t=1e-10)=>assert.ok(Math.abs(a-b)<=t,`${a} vs ${b}`);
const momentum=s=>[0,1,2].map(k=>Array.from(s.massesKg).reduce((sum,m,i)=>sum+m*s.velocitiesXYZ[i*3+k],0));

test('empty world advances without fake particles or pressure',()=>{const w=create();let r=w.step(1/60);assert.equal(r.totalMassKg,0);assert.equal(r.convergence,'converged');assert.equal(r.particleCount,0);assert.equal(w.totalMassKg,0)});
test('isolated particle obeys gravity vector and semi-implicit integration',()=>{const g=V(3,-9.81,-1.5),w=create(g),id=w.addParticle(P(1,2,3,1,V(2,-1,4))),dt=1/120;let r=w.step(dt),p=w.getParticle(id);for(const [key,x,v,a] of [['x',1,2,3],['y',2,-1,-9.81],['z',3,4,-1.5]]){close(p.velocity[key],v+a*dt);close(p.position[key],x+(v+a*dt)*dt)}assert.equal(r.convergence,'converged')});
test('free particle with no forces preserves inertial motion over multiple frames',()=>{const w=create(),id=w.addParticle(P(-1,2,4,1,V(3,0,-2)));for(let i=0;i<30;i++)w.step(1/120);let p=w.getParticle(id);close(p.position.x,-.25);close(p.position.y,2);close(p.position.z,3.5)});
test('compressed fluid pair moves apart under physical pressure',()=>{const w=create(),a=w.addParticle(P(-.075,0,0,50)),b=w.addParticle(P(.075,0,0,50)),r=w.step(1/120);assert.ok(r.densityIterations>0);assert.equal(r.convergence,'converged');assert.ok(w.getParticle(b).position.x-w.getParticle(a).position.x>.15);assert.ok(r.maximumDensityCompressionRelative<=.01);close(w.totalMassKg,100)});
test('pressure impulses preserve total linear momentum for unequal masses',()=>{const w=create();w.addParticle(P(-.05,0,0,30));w.addParticle(P(.05,0,0,42));let before=momentum(w.particleSnapshot()),r=w.step(1/240),after=momentum(w.particleSnapshot());assert.ok(r.densityIterations>0);for(let k=0;k<3;k++)close(after[k],before[k],1e-8)});
test('divergence solver reacts to approaching particles',()=>{const w=create();w.addParticle(P(-.1,0,0,1,V(1,0,0)));w.addParticle(P(.1,0,0,1,V(-1,0,0)));let r=w.step(1/120);assert.ok(r.divergenceIterations>0);assert.ok(r.maximumDivergencePerSecond<=.05+1e-9)});
test('viscosity damps transverse relative speed without momentum loss',()=>{const w=create();w.setLiquidConfig(liquid({kinematicViscosityM2S:1}));let a=w.addParticle(P(-.1,0,0,5,V(0,1,0))),b=w.addParticle(P(.1,0,0,5,V(0,-1,0)));let before=momentum(w.particleSnapshot());w.step(1/120);assert.ok(w.getParticle(a).velocity.y<1&&w.getParticle(a).velocity.y>0);assert.ok(w.getParticle(b).velocity.y>-1&&w.getParticle(b).velocity.y<0);momentum(w.particleSnapshot()).forEach((v,k)=>close(v,before[k],1e-9))});
test('explicit particle mass updates and deletion are reflected in mass accounting',()=>{const w=create(),a=w.addParticle(P(0,0,0,2)),b=w.addParticle(P(2,0,0,3));assert.equal(w.totalMassKg,5);w.step(1/120);assert.equal(w.totalMassKg,5);w.updateParticle(a,{massKg:4});assert.equal(w.totalMassKg,7);w.removeParticle(b);assert.equal(w.totalMassKg,4);w.clearParticles();assert.equal(w.totalMassKg,0)});
test('S02 spatial neighbors use post-step positions with stable ID',()=>{const w=create(),id=w.addParticle(P(0,0,0,1,V(2,0,0)));assert.deepEqual(w.neighborsWithin(V(0,0,0),.001),[id]);w.step(1/120);assert.deepEqual(w.neighborsWithin(V(0,0,0),.001),[]);assert.deepEqual(w.neighborsWithin(w.getParticle(id).position,.001),[id])});
test('CFL rejection never partially publishes a computed step',()=>{const w=new FluidWorld(physical(V(0,0,0),16));w.setLiquidConfig(liquid());w.addParticle(P(0,0,0,1,V(3000,0,0)));let before=w.particleSnapshot();assert.throws(()=>w.step(1/60),fails('STEP_BUDGET_EXCEEDED'));assert.deepEqual(w.particleSnapshot(),before)});
test('nonrepresentable solver grid rejects step atomically',()=>{const w=create();w.addParticle(P(Number.MAX_VALUE/4,0,0));let before=w.particleSnapshot();assert.throws(()=>w.step(1/120),fails('OUT_OF_RANGE'));assert.deepEqual(w.particleSnapshot(),before)});
test('coincident unresolvable compression is reported as iteration_limit',()=>{const w=create();w.addParticle(P(0,0,0,50));w.addParticle(P(0,0,0,50));let r=w.step(1/120);assert.equal(r.convergence,'iteration_limit');assert.ok(r.maximumDensityCompressionRelative>.01);assert.equal(r.densityIterations,w.getLiquidConfig().maxDensityIterations)});
test('invalid solver config rejected atomically and remains immutable',()=>{const w=create(),before=w.getLiquidConfig();for(const o of [{supportRadiusMeters:0},{supportRadiusMeters:NaN},{kinematicViscosityM2S:-1},{maxDensityIterations:0},{maxDivergenceIterations:101},{cflFraction:2},{divergenceTolerancePerSecond:-1},{densityToleranceRelative:Infinity}]){assert.throws(()=>w.setLiquidConfig(liquid(o)));assert.equal(w.getLiquidConfig(),before)}assert.throws(()=>w.setLiquidConfig({supportRadiusMeters:1}),fails('INVALID_ARGUMENT'));assert.ok(Object.isFrozen(before))});
test('worlds are independent and shutdown rejects public solver operations',()=>{const a=create(V(0,-9.81,0)),b=create(),id=a.addParticle(P(1,2,3));a.setLiquidConfig(liquid({supportRadiusMeters:.8}));assert.notEqual(a.getLiquidConfig().supportRadiusMeters,b.getLiquidConfig().supportRadiusMeters);a.step(1/120);assert.ok(a.getParticle(id).position.y<2);assert.equal(b.particleCount,0);a.shutdown();assert.throws(()=>a.step(1/120),fails('CLOSED'));assert.throws(()=>a.totalMassKg,fails('CLOSED'))});
test('multi-frame 3D block is finite with mass and stable particle IDs',()=>{const w=create(V(0,-9.81,0)),ids=[];for(let x=0;x<4;x++)for(let y=0;y<4;y++)for(let z=0;z<4;z++)ids.push(w.addParticle(P(x*.12,y*.12+2,z*.12,1.728)));const mass=w.totalMassKg,old=w.particleSnapshot().positionsXYZ;for(let i=0;i<12;i++){let r=w.step(1/120);close(r.totalMassKg,mass,1e-10);assert.ok(Number.isFinite(r.maximumDensityCompressionRelative));assert.ok(Number.isFinite(r.maximumDivergencePerSecond))}const snap=w.particleSnapshot();close(w.totalMassKg,mass,1e-10);assert.deepEqual([...snap.ids],ids);assert.ok(snap.positionsXYZ[1]<old[1]);for(const v of [...snap.positionsXYZ,...snap.velocitiesXYZ])assert.ok(Number.isFinite(v))});
test('batch emission and drain validate atomically, preserve mass and unique IDs',()=>{const w=new FluidWorld(physical(),{maxParticles:4}),[a,b]=w.emitParticles([P(0,0,0,2),P(1,0,0,3)]);assert.deepEqual([a,b],[1,2]);const before=w.particleSnapshot();assert.throws(()=>w.emitParticles([P(2,0,0,4),P(3,0,0,-1)]),fails('NON_POSITIVE'));assert.throws(()=>w.emitParticles([P(2,0,0),P(3,0,0),P(4,0,0)]),fails('CAPACITY_EXCEEDED'));assert.throws(()=>w.drainParticles([a,999]),fails('NOT_FOUND'));assert.throws(()=>w.drainParticles([a,a]),fails('INVALID_ARGUMENT'));assert.deepEqual(w.particleSnapshot(),before);assert.equal(w.drainParticles([a]),2);const[c]=w.emitParticles([P(2,0,0,1.5)]);assert.equal(c,3);assert.equal(w.totalMassKg,4.5);assert.equal(w.drainParticles([b,c]),4.5);assert.equal(w.totalMassKg,0)});
